import {
  DEFAULT_REDACTION_SETTINGS,
  type RedactionSettings,
  ENVIRONMENTS,
  ERROR_TYPES,
  EVALUATION_KINDS,
  EVALUATION_SOURCES,
  ORGANIZATION_ROLES,
  SPAN_KINDS,
  TRACE_STATUSES,
} from '@tracemind/shared';
import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

/*
 * Conventions
 * - UUID primary keys generated by PostgreSQL (gen_random_uuid, built into PG 13+).
 * - All timestamps are timestamptz.
 * - Telemetry tables (traces, spans, token_usage, errors, evaluations) carry project_id even when
 *   it is derivable through a parent, so every tenant-scoped query filters on an indexed column
 *   and never needs a join to enforce isolation.
 * - Raw telemetry is preserved; aggregates are computed from it (see docs/ARCHITECTURE.md).
 */

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/* --------------------------------------------------------------------- enums */

export const organizationRole = pgEnum('organization_role', ORGANIZATION_ROLES);
export const environment = pgEnum('environment', ENVIRONMENTS);
export const traceStatus = pgEnum('trace_status', TRACE_STATUSES);
export const spanKind = pgEnum('span_kind', SPAN_KINDS);
export const errorType = pgEnum('error_type', ERROR_TYPES);
export const evaluationKind = pgEnum('evaluation_kind', EVALUATION_KINDS);
export const evaluationSource = pgEnum('evaluation_source', EVALUATION_SOURCES);

/* ------------------------------------------------------------- identity/tenancy */

export const users = pgTable('users', {
  id: uuid('id').primaryKey().defaultRandom(),
  /** Always stored lowercased (normalized by the shared email schema). */
  email: text('email').notNull().unique(),
  name: text('name').notNull(),
  passwordHash: text('password_hash').notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const organizations = pgTable('organizations', {
  id: uuid('id').primaryKey().defaultRandom(),
  name: text('name').notNull(),
  slug: text('slug').notNull().unique(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const organizationMembers = pgTable(
  'organization_members',
  {
    organizationId: uuid('organization_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: organizationRole('role').notNull().default('member'),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.organizationId, t.userId] }),
    index('organization_members_user_idx').on(t.userId),
  ],
);

export const projects = pgTable(
  'projects',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    organizationId: uuid('organization_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    description: text('description'),
    /** Raw telemetry older than this is eligible for deletion by the retention job. */
    retentionDays: integer('retention_days').notNull().default(30),
    /** Masking applied to telemetry before it is queued or stored. */
    redaction: jsonb('redaction')
      .$type<RedactionSettings>()
      .notNull()
      .default(DEFAULT_REDACTION_SETTINGS),
    /** Demo projects hold simulated telemetry and are labelled as such in the UI. */
    isDemo: boolean('is_demo').notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    archivedAt: timestamp('archived_at', { withTimezone: true }),
  },
  (t) => [
    uniqueIndex('projects_org_slug_uq').on(t.organizationId, t.slug),
    check('projects_retention_days_ck', sql`${t.retentionDays} BETWEEN 1 AND 3650`),
  ],
);

export const apiKeys = pgTable(
  'api_keys',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    /** Public, non-secret part shown in the UI to identify the key. */
    prefix: text('prefix').notNull(),
    /** SHA-256 (hex) of the full key. Keys are 192-bit random, so a fast hash is appropriate. */
    keyHash: text('key_hash').notNull().unique(),
    /** Default environment attached to telemetry ingested with this key. */
    environment: environment('environment').notNull().default('development'),
    createdById: uuid('created_by_id').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
  },
  (t) => [index('api_keys_project_idx').on(t.projectId)],
);

/* ------------------------------------------------------------ model catalogue */

export const modelProviders = pgTable('model_providers', {
  /** Stable slug, e.g. `openai`, `anthropic`, `google`. */
  id: text('id').primaryKey(),
  displayName: text('display_name').notNull(),
  createdAt: createdAt(),
});

/**
 * Versioned price list. A row is valid in [effective_from, effective_to). Costs are resolved
 * against the row valid at the span's start time, so price changes never rewrite history and
 * historical costs can be recomputed deterministically.
 */
export const modelPricing = pgTable(
  'model_pricing',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    providerId: text('provider_id')
      .notNull()
      .references(() => modelProviders.id, { onDelete: 'restrict' }),
    model: text('model').notNull(),
    currency: text('currency').notNull().default('USD'),
    inputPricePerMillion: numeric('input_price_per_million', { precision: 14, scale: 6 }).notNull(),
    outputPricePerMillion: numeric('output_price_per_million', {
      precision: 14,
      scale: 6,
    }).notNull(),
    cachedInputPricePerMillion: numeric('cached_input_price_per_million', {
      precision: 14,
      scale: 6,
    }),
    effectiveFrom: timestamp('effective_from', { withTimezone: true }).notNull(),
    effectiveTo: timestamp('effective_to', { withTimezone: true }),
    source: text('source'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('model_pricing_provider_model_from_uq').on(t.providerId, t.model, t.effectiveFrom),
    check(
      'model_pricing_window_ck',
      sql`${t.effectiveTo} IS NULL OR ${t.effectiveTo} > ${t.effectiveFrom}`,
    ),
  ],
);

/* ----------------------------------------------------------------- telemetry */

export const traces = pgTable(
  'traces',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    /** Client-supplied identifier (SDK or OTel trace id). Idempotency key for ingestion. */
    externalId: text('external_id').notNull(),
    name: text('name').notNull(),
    environment: environment('environment').notNull(),
    status: traceStatus('status').notNull().default('running'),
    /** End-user identifier from the instrumented application (not a TraceMind user). */
    endUserId: text('end_user_id'),
    sessionId: text('session_id'),
    tags: text('tags')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    /** End-to-end input/output of the request (e.g. user question and final answer). */
    input: jsonb('input'),
    output: jsonb('output'),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    endedAt: timestamp('ended_at', { withTimezone: true }),
    durationMs: integer('duration_ms'),
    /** False while only spans referencing this trace have arrived (no trace event yet). */
    isComplete: boolean('is_complete').notNull().default(true),
    isSimulated: boolean('is_simulated').notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('traces_project_external_uq').on(t.projectId, t.externalId),
    index('traces_project_started_idx').on(t.projectId, t.startedAt.desc()),
    index('traces_project_env_started_idx').on(t.projectId, t.environment, t.startedAt.desc()),
    index('traces_session_idx').on(t.projectId, t.sessionId),
  ],
);

export const spans = pgTable(
  'spans',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    traceId: uuid('trace_id')
      .notNull()
      .references(() => traces.id, { onDelete: 'cascade' }),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    parentSpanId: uuid('parent_span_id').references((): AnyPgColumn => spans.id, {
      onDelete: 'cascade',
    }),
    externalId: text('external_id').notNull(),
    /**
     * Client-side parent id. parent_span_id is resolved from it once the parent has arrived, so
     * children may be ingested before their parents.
     */
    parentExternalId: text('parent_external_id'),
    name: text('name').notNull(),
    kind: spanKind('kind').notNull().default('custom'),
    status: traceStatus('status').notNull().default('running'),
    providerId: text('provider_id').references(() => modelProviders.id, { onDelete: 'set null' }),
    model: text('model'),
    /** Prompt/messages and completion, after redaction. */
    input: jsonb('input'),
    output: jsonb('output'),
    modelParameters: jsonb('model_parameters').$type<Record<string, unknown>>(),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    endedAt: timestamp('ended_at', { withTimezone: true }),
    durationMs: integer('duration_ms'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('spans_trace_external_uq').on(t.traceId, t.externalId),
    index('spans_trace_idx').on(t.traceId, t.startedAt),
    index('spans_parent_idx').on(t.parentSpanId),
    index('spans_project_started_idx').on(t.projectId, t.startedAt.desc()),
    index('spans_project_model_started_idx').on(t.projectId, t.model, t.startedAt.desc()),
  ],
);

/**
 * Token usage and cost per LLM span (1:1). Kept separate from spans so cost can be recomputed
 * (e.g. after a pricing correction) without touching the span payload.
 */
export const tokenUsage = pgTable(
  'token_usage',
  {
    spanId: uuid('span_id')
      .primaryKey()
      .references(() => spans.id, { onDelete: 'cascade' }),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    inputTokens: integer('input_tokens').notNull().default(0),
    outputTokens: integer('output_tokens').notNull().default(0),
    cachedInputTokens: integer('cached_input_tokens').notNull().default(0),
    totalTokens: integer('total_tokens').notNull().default(0),
    /** Computed by TraceMind from model_pricing. Null when no price was known. */
    estimatedCostUsd: numeric('estimated_cost_usd', { precision: 18, scale: 8 }),
    /** Reported by the provider/client, when available. Never overwritten by estimates. */
    reportedCostUsd: numeric('reported_cost_usd', { precision: 18, scale: 8 }),
    pricingId: uuid('pricing_id').references(() => modelPricing.id, { onDelete: 'set null' }),
    recordedAt: timestamp('recorded_at', { withTimezone: true }).notNull(),
  },
  (t) => [
    index('token_usage_project_recorded_idx').on(t.projectId, t.recordedAt.desc()),
    check(
      'token_usage_non_negative_ck',
      sql`${t.inputTokens} >= 0 AND ${t.outputTokens} >= 0 AND ${t.cachedInputTokens} >= 0 AND ${t.totalTokens} >= 0`,
    ),
  ],
);

export const telemetryErrors = pgTable(
  'errors',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    traceId: uuid('trace_id')
      .notNull()
      .references(() => traces.id, { onDelete: 'cascade' }),
    spanId: uuid('span_id').references(() => spans.id, { onDelete: 'cascade' }),
    type: errorType('type').notNull().default('unknown'),
    message: text('message').notNull(),
    code: text('code'),
    httpStatus: integer('http_status'),
    stack: text('stack'),
    providerId: text('provider_id').references(() => modelProviders.id, { onDelete: 'set null' }),
    model: text('model'),
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    occurredAt: timestamp('occurred_at', { withTimezone: true }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('errors_project_occurred_idx').on(t.projectId, t.occurredAt.desc()),
    index('errors_project_type_occurred_idx').on(t.projectId, t.type, t.occurredAt.desc()),
    index('errors_trace_idx').on(t.traceId),
    // Ingestion upserts at most one error per span, and one trace-level error per trace.
    uniqueIndex('errors_span_uq')
      .on(t.spanId)
      .where(sql`${t.spanId} IS NOT NULL`),
    uniqueIndex('errors_trace_level_uq')
      .on(t.traceId)
      .where(sql`${t.spanId} IS NULL`),
  ],
);

export const evaluations = pgTable(
  'evaluations',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    projectId: uuid('project_id')
      .notNull()
      .references(() => projects.id, { onDelete: 'cascade' }),
    traceId: uuid('trace_id')
      .notNull()
      .references(() => traces.id, { onDelete: 'cascade' }),
    spanId: uuid('span_id').references(() => spans.id, { onDelete: 'cascade' }),
    /** Client idempotency key (optional). */
    externalId: text('external_id'),
    /** e.g. `helpfulness`, `correctness`, `user_feedback`. */
    criterion: text('criterion').notNull(),
    kind: evaluationKind('kind').notNull(),
    /** thumbs: 0 or 1; numeric: any value within the criterion's scale. */
    score: doublePrecision('score'),
    /** categorical label, or free-form label for other kinds. */
    label: text('label'),
    comment: text('comment'),
    source: evaluationSource('source').notNull(),
    createdById: uuid('created_by_id').references(() => users.id, { onDelete: 'set null' }),
    createdAt: createdAt(),
  },
  (t) => [
    index('evaluations_project_created_idx').on(t.projectId, t.createdAt.desc()),
    index('evaluations_trace_idx').on(t.traceId),
    uniqueIndex('evaluations_project_external_uq')
      .on(t.projectId, t.externalId)
      .where(sql`${t.externalId} IS NOT NULL`),
    check('evaluations_thumbs_score_ck', sql`${t.kind} <> 'thumbs' OR ${t.score} IN (0, 1)`),
  ],
);

/** Bookkeeping for the ingestion pipeline (dead-letter for payloads that failed processing). */
export const ingestionFailures = pgTable(
  'ingestion_failures',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    projectId: uuid('project_id').references(() => projects.id, { onDelete: 'cascade' }),
    reason: text('reason').notNull(),
    payload: jsonb('payload'),
    createdAt: createdAt(),
  },
  (t) => [index('ingestion_failures_project_created_idx').on(t.projectId, t.createdAt.desc())],
);

export type User = typeof users.$inferSelect;
export type Organization = typeof organizations.$inferSelect;
export type OrganizationMember = typeof organizationMembers.$inferSelect;
export type Project = typeof projects.$inferSelect;
export type ApiKey = typeof apiKeys.$inferSelect;
export type ModelPricing = typeof modelPricing.$inferSelect;
